insert into public.football_player_profiles (player_id, name_ko, sort, intro) values
(168299, '김민재', 10, $p$<p>김민재는 "괴물"이라는 별명으로 불리는 한국 대표팀의 중앙 수비수입니다. 전북 현대에서 프로 생활을 시작해 베이징 궈안과 튀르키예의 페네르바흐체를 거쳐 2022년 나폴리로 이적했고, 첫 시즌 33년 만의 세리에 A 우승을 이끌며 리그 최우수 수비수로 뽑혔습니다. 2023년에는 바이에른 뮌헨으로 옮겨 분데스리가 우승을 경험했습니다.</p><p>토리코리 관전 포인트: 김민재는 빠른 발과 넓은 수비 범위를 바탕으로 높은 수비 라인을 지탱하는 유형입니다. 소속팀의 경기당 실점과 무실점 경기 수가 그의 활약을 가늠하는 가장 좋은 지표입니다.</p>$p$),
(213217, '이강인', 20, $p$<p>이강인은 어린 시절 방송 프로그램으로 얼굴을 알린 뒤 열 살에 스페인 발렌시아 유소년 팀에 입단한 미드필더입니다. 2019년 U-20 월드컵에서 한국의 준우승을 이끌며 골든볼을 받았고, 마요르카를 거쳐 2023년 파리 생제르맹으로 이적해 리그 우승과 2024-25 시즌 챔피언스리그 우승을 함께 경험했습니다. 2022 항저우 아시안게임 금메달의 주역이기도 합니다.</p><p>토리코리 관전 포인트: 이강인은 왼발 킥과 탈압박, 세트피스 전담 능력이 강점입니다. 골보다 도움과 기회 창출로 팀에 기여하는 선수라, 득점 순위의 도움 기록을 함께 보면 활약이 더 잘 드러납니다.</p>$p$),
(3354, '황희찬', 30, $p$<p>황희찬은 저돌적인 돌파 덕분에 "황소"라는 별명을 얻은 공격수입니다. 포항 스틸러스 유스 출신으로 오스트리아 레드불 잘츠부르크에서 유럽 무대에 데뷔했고, RB 라이프치히와 함부르크를 거쳐 2021년 잉글랜드 울버햄프턴으로 옮겨 프리미어리그에서 활약했습니다. 2022 카타르 월드컵 포르투갈전 추가시간 결승골로 한국의 16강 진출을 이끈 장면은 지금도 회자됩니다.</p><p>토리코리 관전 포인트: 황희찬은 수비 뒷공간을 파고드는 침투와 역습 상황에서 가장 위협적입니다. 소속팀이 역습 위주로 경기하는 원정 경기에서 공격 포인트가 나오는지 지켜보세요.</p>$p$),
(170561, '황인범', 40, $p$<p>황인범은 넓은 시야와 정확한 패스로 대표팀 중원을 이끄는 미드필더입니다. 대전 시티즌에서 프로에 데뷔해 미국 밴쿠버 화이트캡스, 러시아 루빈 카잔, 그리스 올림피아코스, 세르비아 츠르베나 즈베즈다를 거쳐 2024년 네덜란드 페예노르트로 이적했습니다. 여러 리그를 거치며 쌓은 적응력이 큰 장점입니다.</p><p>토리코리 관전 포인트: 황인범 같은 중앙 미드필더의 영향력은 소속팀의 점유율과 경기 운영에서 드러납니다. 팀이 전반을 앞선 경기에서 리드를 잘 지키는지 함께 보면 좋습니다.</p>$p$),
(72432, '정우영', 50, $p$<p>정우영은 바이에른 뮌헨 유소년 팀과 2군을 거쳐 유럽에서 성장한 공격형 미드필더입니다. SC 프라이부르크와 VfB 슈투트가르트에서 분데스리가 경험을 쌓았고, 이후 우니온 베를린으로 옮겼습니다. 2022 항저우 아시안게임에서는 득점왕에 오르며 금메달을 이끌었습니다.</p><p>토리코리 관전 포인트: 정우영은 많은 활동량과 압박으로 팀에 기여하는 선수입니다. 교체로 나서는 경기가 많을 때는 소속팀의 후반 득점 비율이 그의 역할을 가늠하는 참고가 됩니다.</p>$p$),
(151888, '옌스 카스트로프', 60, $p$<p>옌스 카스트로프는 독일에서 한국인 어머니와 독일인 아버지 사이에서 태어난 미드필더입니다. 독일 연령별 대표를 거쳤지만 2025년 한국 대표팀을 선택해 큰 화제가 됐습니다. 쾰른 유소년 팀을 거쳐 2부 리그 뉘른베르크에서 주전으로 활약한 뒤, 보루시아 묀헨글라트바흐로 이적하며 분데스리가 무대에 섰습니다.</p><p>토리코리 관전 포인트: 카스트로프는 적극적인 압박과 몸싸움, 많은 활동량이 강점인 선수입니다. 소속팀이 상대에게 내주는 경기당 실점과 중원 싸움의 결과를 함께 지켜보면 그의 역할이 보입니다.</p>$p$),
(180775, '홍현석', 70, $p$<p>홍현석은 울산 현대 유스 출신으로, 독일 하부리그와 오스트리아 LASK를 거쳐 벨기에 KAA 헨트에서 주전으로 자리 잡으며 이름을 알린 미드필더입니다. 헨트에서의 활약을 바탕으로 2024년 분데스리가 마인츠로 이적했습니다.</p><p>토리코리 관전 포인트: 홍현석은 왼발 중거리 슛과 전진 패스가 강점입니다. 박스 밖에서 슈팅 기회를 만드는 선수라, 소속팀 득점이 막힐 때 해결사 역할을 할 수 있을지 지켜볼 만합니다.</p>$p$),
(217715, '이한범', 80, $p$<p>이한범은 FC 서울에서 프로에 데뷔한 중앙 수비수로, 2023년 덴마크 미트윌란으로 이적하며 유럽 무대에 진출했습니다. 190cm에 가까운 큰 키와 안정적인 빌드업 능력을 갖춰 대표팀의 차세대 수비수로 꼽힙니다.</p><p>토리코리 관전 포인트: 젊은 수비수는 유럽대항전 같은 큰 무대 경험이 성장의 열쇠입니다. 소속팀의 챔피언스리그 경기 실점과 무실점 경기 수를 함께 보면 좋습니다.</p>$p$),
(221783, '김지수', 90, $p$<p>김지수는 성남 FC에서 10대에 프로 무대에 데뷔한 중앙 수비수입니다. 2023년 만 18세의 나이로 프리미어리그 브렌트퍼드에 입단하며 한국 수비수의 잉글랜드 진출이라는 새 길을 열었습니다. 큰 키와 침착한 볼 처리가 장점으로 꼽힙니다.</p><p>토리코리 관전 포인트: 어린 수비수에게는 꾸준한 출전 기회가 가장 중요합니다. 소속팀의 수비 지표와 함께 출전 흐름을 지켜보며 성장 과정을 따라가 보세요.</p>$p$),
(243858, '설영우', 100, $p$<p>설영우는 울산 HD에서 K리그1 우승을 경험한 측면 수비수로, 좌우 양쪽을 모두 소화할 수 있는 멀티 플레이어입니다. 2024년 세르비아 츠르베나 즈베즈다로 이적해 챔피언스리그 무대를 밟으며 유럽 경력을 시작했습니다.</p><p>토리코리 관전 포인트: 측면 수비수의 공격 가담은 도움 기록으로 드러납니다. 소속팀이 측면을 활용해 골을 만드는 경기가 많은지, 그리고 설영우가 공격 포인트를 쌓는지 함께 보세요.</p>$p$)
